package main

import (
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// tokenType enumerates the kinds of tokens that make up a statement.
type tokenType int

const (
	tBare tokenType = iota // bare identifier (the root word or a key)
	tNumericKey            // array index inside brackets
	tQuotedKey             // quoted object key inside brackets
	tLBrace                // [
	tRBrace                // ]
	tDot                   // .
	tValueSep              // " = "
	tSemi                  // ;
	tEmptyObject           // {}
	tEmptyArray            // []
	tString                // string value (quoted)
	tNumber                // numeric value (or any raw value text)
	tTrue
	tFalse
	tNull
	tError   // lexing failed here; renders as nothing
	tIgnored // trailing text that is kept for display only
)

type token struct {
	typ  tokenType
	text string
}

// render returns the plain textual form of a token.
func (t token) render() string {
	switch t.typ {
	case tValueSep:
		return " = "
	case tError:
		return ""
	}
	return t.text
}

// isValue reports whether the token represents a JSON value.
func (t token) isValue() bool {
	switch t.typ {
	case tEmptyObject, tEmptyArray, tString, tNumber, tTrue, tFalse, tNull:
		return true
	}
	return false
}

// ANSI colouring helpers, mirroring the style of common terminal colour libs.
const (
	escape = "\x1b["
)

type colour struct {
	on  string
	off string
}

func mkColour(attrs ...int) colour {
	ons := make([]string, len(attrs))
	offs := make([]string, len(attrs))
	for i, a := range attrs {
		ons[i] = strconv.Itoa(a)
		switch a {
		case 1, 2:
			offs[i] = "22"
		case 3:
			offs[i] = "23"
		case 4:
			offs[i] = "24"
		case 5, 6:
			offs[i] = "25"
		case 7:
			offs[i] = "27"
		case 8:
			offs[i] = "28"
		case 9:
			offs[i] = "29"
		default:
			offs[i] = "0"
		}
	}
	return colour{
		on:  escape + strings.Join(ons, ";") + "m",
		off: escape + strings.Join(offs, ";") + "m",
	}
}

func (c colour) wrap(s string) string {
	return c.on + s + c.off
}

var (
	colKey    = mkColour(34, 1) // blue, bold
	colBrace  = mkColour(35)    // magenta
	colNumber = mkColour(31)    // red
	colString = mkColour(33)    // yellow
	colBool   = mkColour(36)    // cyan
	colQuote  = mkColour(32)    // green
	colPunct  = mkColour(1)     // bold
)

// renderColour returns the coloured textual form of a token.
func (t token) renderColour() string {
	switch t.typ {
	case tBare:
		return colKey.wrap(t.text)
	case tNumericKey, tNumber:
		return colNumber.wrap(t.text)
	case tQuotedKey, tString:
		return colString.wrap(t.text)
	case tLBrace, tRBrace, tEmptyObject, tEmptyArray:
		return colBrace.wrap(t.text)
	case tTrue, tFalse, tNull:
		return colBool.wrap(t.text)
	case tValueSep:
		return " = "
	case tError:
		return ""
	}
	return t.text
}

// quoteString produces the JavaScript/JSON compatible quoted form of s
// used in gron output. Forward slashes and HTML characters are left as-is,
// control characters and the line/paragraph separators are \u escaped.
func quoteString(s string) string {
	var b strings.Builder
	b.Grow(len(s) + 2)
	b.WriteByte('"')
	for i := 0; i < len(s); {
		r, size := utf8.DecodeRuneInString(s[i:])
		i += size
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if unicode.IsControl(r) || r == '\u2028' || r == '\u2029' {
				b.WriteString(`\u`)
				h := strings.ToUpper(strconv.FormatInt(int64(r), 16))
				for pad := len(h); pad < 4; pad++ {
					b.WriteByte('0')
				}
				b.WriteString(h)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}
EOF
