func isIdentStart(r rune) bool {
	if r == '$' || r == '_' {
		return true
	}
	if r < utf8.RuneSelf {
		return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
	}
	return unicode.In(r, identStartTables...)
}

// isIdentPart reports whether r may continue a bare identifier.
func isIdentPart(r rune) bool {
	if isIdentStart(r) {
		return true
	}
	if r < utf8.RuneSelf {
		return r >= '0' && r <= '9'
	}
	return unicode.In(r, identPartTables...)
}

