package main

import (
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// statement is a single gron assignment, e.g. `json.foo[0] = "bar";`.
type statement []token

type statements []statement

// String renders the statement as plain text.
func (s statement) String() string {
	var b strings.Builder
	for _, t := range s {
		b.WriteString(t.render())
	}
	return b.String()
}

// colourString renders the statement with ANSI colours.
func (s statement) colourString() string {
	var b strings.Builder
	for _, t := range s {
		b.WriteString(t.renderColour())
	}
	return b.String()
}

// jsonString renders the statement as a JSON stream line: [[path...], value]
func (s statement) jsonString(colour bool) string {
	var b strings.Builder
	lb, rb := "[", "]"
	if colour {
		lb, rb = colBrace.wrap("["), colBrace.wrap("]")
	}
	b.WriteString(lb)
	b.WriteString(lb)
	first := true
	var value token
	for _, t := range s {
		switch t.typ {
		case tBare:
			if !first {
				b.WriteString(",")
			}
			first = false
			q := quoteString(t.text)
			if colour {
				q = colString.wrap(q)
			}
			b.WriteString(q)
		case tQuotedKey:
			if !first {
				b.WriteString(",")
			}
			first = false
			if colour {
				b.WriteString(colString.wrap(t.text))
			} else {
				b.WriteString(t.text)
			}
		case tNumericKey:
			if !first {
				b.WriteString(",")
			}
			first = false
			if colour {
				b.WriteString(colNumber.wrap(t.text))
			} else {
				b.WriteString(t.text)
			}
		default:
			if t.isValue() {
				value = t
			}
		}
	}
	b.WriteString(rb)
	b.WriteString(",")
	if colour {
		b.WriteString(value.renderColour())
	} else {
		b.WriteString(value.render())
	}
	b.WriteString(rb)
	return b.String()
}

// withKey returns a copy of the path with an object key appended.
func (s statement) withKey(k string) statement {
	n := make(statement, 0, len(s)+3)
	n = append(n, s...)
	if validIdentifier(k) {
		n = append(n, token{tDot, "."}, token{tBare, k})
	} else {
		n = append(n, token{tLBrace, "["}, token{tQuotedKey, quoteString(k)}, token{tRBrace, "]"})
	}
	return n
}

// withIndex returns a copy of the path with an array index appended.
func (s statement) withIndex(i int) statement {
	n := make(statement, 0, len(s)+3)
	n = append(n, s...)
	n = append(n, token{tLBrace, "["}, token{tNumericKey, strconv.Itoa(i)}, token{tRBrace, "]"})
	return n
}

// assign returns a full statement: path = value;
func (s statement) assign(v token) statement {
	n := make(statement, 0, len(s)+3)
	n = append(n, s...)
	n = append(n, token{tValueSep, " = "}, v, token{tSemi, ";"})
	return n
}

// valueToken converts a decoded JSON scalar (or empty container) into a token.
func valueToken(v interface{}) (token, bool) {
	switch vv := v.(type) {
	case nil:
		return token{tNull, "null"}, true
	case bool:
		if vv {
			return token{tTrue, "true"}, true
		}
		return token{tFalse, "false"}, true
	case json.Number:
		return token{tNumber, vv.String()}, true
	case float64:
		b, _ := json.Marshal(vv)
		return token{tNumber, string(b)}, true
	case string:
		return token{tString, quoteString(vv)}, true
	case map[string]interface{}:
		if len(vv) == 0 {
			return token{tEmptyObject, "{}"}, true
		}
	case []interface{}:
		if len(vv) == 0 {
			return token{tEmptyArray, "[]"}, true
		}
	}
	return token{}, false
}

// addValue appends statements describing v at the given path.
func (ss *statements) addValue(path statement, v interface{}) {
	switch vv := v.(type) {
	case map[string]interface{}:
		*ss = append(*ss, path.assign(token{tEmptyObject, "{}"}))
		for k, child := range vv {
			ss.addValue(path.withKey(k), child)
		}
	case []interface{}:
		*ss = append(*ss, path.assign(token{tEmptyArray, "[]"}))
		for i, child := range vv {
			ss.addValue(path.withIndex(i), child)
		}
	default:
		t, ok := valueToken(v)
		if !ok {
			t = token{tNumber, fmt.Sprintf("%v", v)}
		}
		*ss = append(*ss, path.assign(t))
	}
}

// makeStatements builds the complete list of statements for a JSON value
// rooted at the given prefix.
func makeStatements(prefix statement, v interface{}) statements {
	ss := make(statements, 0, 64)
	ss.addValue(prefix, v)
	return ss
}

// compareTokens orders two tokens; numeric keys are compared numerically.
func compareTokens(a, b token) int {
	if a.typ == tNumericKey && b.typ == tNumericKey {
		ai, aerr := strconv.Atoi(a.text)
		bi, berr := strconv.Atoi(b.text)
		if aerr == nil && berr == nil {
			switch {
			case ai < bi:
				return -1
			case ai > bi:
				return 1
			default:
				return 0
			}
		}
	}
	return strings.Compare(a.render(), b.render())
}

// less orders statements token by token.
func (s statement) less(o statement) bool {
	n := len(s)
	if len(o) < n {
		n = len(o)
	}
	for i := 0; i < n; i++ {
		if c := compareTokens(s[i], o[i]); c != 0 {
			return c < 0
		}
	}
	return len(s) < len(o)
}

func (ss statements) sort() {
	sort.Slice(ss, func(i, j int) bool {
		return ss[i].less(ss[j])
	})
}

// --- ungron side -----------------------------------------------------------

// statementFromJSON converts a JSON stream line `[[path...], value]` into a
// statement.
func statementFromJSON(line []byte) (statement, error) {
	var raw []interface{}
	if err := json.Unmarshal(line, &raw); err != nil {
		return nil, err
	}
	if len(raw) != 2 {
		return nil, errInvalidLayout
	}
	path, ok := raw[0].([]interface{})
	if !ok {
		return nil, errInvalidLayout
	}
	s := statement{token{tBare, "json"}}
	for _, p := range path {
		switch pv := p.(type) {
		case string:
			s = s.withKey(pv)
		case float64:
			b, _ := json.Marshal(pv)
			s = append(s, token{tLBrace, "["}, token{tNumericKey, string(b)}, token{tRBrace, "]"})
		default:
			return nil, errInvalidLayout
		}
	}
	v, ok := valueToken(raw[1])
	if !ok {
		return nil, errInvalidLayout
	}
	return s.assign(v), nil
}

var errInvalidLayout = fmt.Errorf("invalid JSON layout")

// toInterface merges all statements into a single value.
func (ss statements) toInterface() (interface{}, error) {
	var result interface{}
	count := 0
	for _, s := range ss {
		v, skip, err := ungronStatement(s)
		if err != nil {
			return nil, fmt.Errorf("ungron failed for `%s`: %s", s, err)
		}
		if skip {
			continue
		}
		count++
		result, err = mergeValues(result, v)
		if err != nil {
			return nil, fmt.Errorf("failed to merge statements: %s", err)
		}
	}
	if count == 0 {
		return nil, fmt.Errorf("no statements were parsed")
	}
	return result, nil
}
EOF
echo ok"}

