package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

var (
	errInvalidStatement = errors.New("invalid statement")
	errNoValue          = errors.New("statement has no value")
)

// ungronStatement validates a statement and turns it into a value.
// skip is true when the statement carries no information (e.g. blank lines
// or a lone root word) and should be silently ignored.
func ungronStatement(s statement) (v interface{}, skip bool, err error) {
	if len(s) == 0 {
		return nil, true, nil
	}
	for _, t := range s {
		if t.typ == tError {
			return nil, false, errInvalidStatement
		}
	}
	if len(s) == 1 {
		return nil, true, nil
	}
	if s[len(s)-1].typ != tSemi {
		return nil, false, errNoValue
	}
	// strip the root word
	if s[0].typ == tBare && s[0].text == "json" {
		s = s[1:]
	}
	v, err = ungronTokens(s)
	if err != nil {
		return nil, false, err
	}
	return v, false, nil
}

// ungronTokens recursively builds the value described by the tokens.
func ungronTokens(ts []token) (interface{}, error) {
	if len(ts) == 0 {
		return nil, errNoValue
	}
	switch ts[0].typ {
	case tBare:
		child, err := ungronTokens(ts[1:])
		if err != nil {
			return nil, err
		}
		return map[string]interface{}{ts[0].text: child}, nil

	case tDot:
		if len(ts) < 2 || ts[1].typ != tBare {
			return nil, errInvalidStatement
		}
		child, err := ungronTokens(ts[2:])
		if err != nil {
			return nil, err
		}
		return map[string]interface{}{ts[1].text: child}, nil

	case tLBrace:
		if len(ts) < 3 || ts[2].typ != tRBrace {
			return nil, errInvalidStatement
		}
		switch ts[1].typ {
		case tNumericKey:
			key, err := strconv.Atoi(ts[1].text)
			if err != nil {
				return nil, fmt.Errorf("invalid integer key `%s`", ts[1].text)
			}
			child, err := ungronTokens(ts[3:])
			if err != nil {
				return nil, err
			}
			arr := make([]interface{}, key+1)
			arr[key] = child
			return arr, nil
		case tQuotedKey:
			child, err := ungronTokens(ts[3:])
			if err != nil {
				return nil, err
			}
			var key string
			if err := json.Unmarshal([]byte(ts[1].text), &key); err != nil {
				return nil, fmt.Errorf("invalid quoted key `%s`", ts[1].text)
			}
			return map[string]interface{}{key: child}, nil
		default:
			return nil, errInvalidStatement
		}

	case tValueSep:
		if len(ts) < 3 || !ts[1].isValue() || ts[2].typ != tSemi {
			return nil, errNoValue
		}
		return decodeValue(ts[1])

	default:
		return nil, errNoValue
	}
}

// decodeValue parses the text of a value token as JSON.
func decodeValue(t token) (interface{}, error) {
	d := json.NewDecoder(strings.NewReader(t.text))
	d.UseNumber()
	var v interface{}
	if err := d.Decode(&v); err != nil {
		return nil, fmt.Errorf("invalid value `%s`", t.text)
	}
	return v, nil
}

// mergeValues combines b into a. Objects and arrays are merged recursively;
// anything else is replaced by b.
func mergeValues(a, b interface{}) (interface{}, error) {
	switch av := a.(type) {
	case map[string]interface{}:
		bv, ok := b.(map[string]interface{})
		if !ok {
			return nil, errors.New("cannot merge object with non-object")
		}
		for k, v := range bv {
			if existing, ok := av[k]; ok {
				merged, err := mergeValues(existing, v)
				if err != nil {
					return nil, err
				}
				av[k] = merged
			} else {
				av[k] = v
			}
		}
		return av, nil

	case []interface{}:
		bv, ok := b.([]interface{})
		if !ok {
			return nil, errors.New("cannot merge array with non-array")
		}
		for len(av) < len(bv) {
			av = append(av, nil)
		}
		for i, v := range bv {
			if v == nil {
				continue
			}
			merged, err := mergeValues(av[i], v)
			if err != nil {
				return nil, err
			}
			av[i] = merged
		}
		return av, nil
	}
	return b, nil
}
