type httpConfig struct {
	insecure bool
	proxy    string
	proxySet bool
	noproxy  string
}

// noProxyFor reports whether host is listed in the comma separated noproxy
// list. Entries beginning with a dot match as a domain suffix.
func noProxyFor(list, host string) bool {
	if list == "" {
		return false
	}
	for _, entry := range strings.Split(list, ",") {
		if entry == "" {
			continue
		}
		if host == entry {
			return true
		}
		if strings.HasPrefix(entry, ".") && strings.HasSuffix(host, entry) {
			return true
		}
	}
	return false
}

// proxyFunc builds the proxy selection function used by the transport.
func proxyFunc(cfg httpConfig) func(*http.Request) (*url.URL, error) {
	return func(req *http.Request) (*url.URL, error) {
		noproxy := cfg.noproxy
		if noproxy == "" {
			noproxy = os.Getenv("no_proxy")
		}
		if noProxyFor(noproxy, req.URL.Host) {
			return nil, nil
		}

		var proxy string
		if cfg.proxySet {
			proxy = cfg.proxy
		} else {
			proxy = os.Getenv(strings.ToLower(req.URL.Scheme) + "_proxy")
		}
		if proxy == "" {
			return nil, nil
		}
		u, err := url.Parse(proxy)
		if err != nil {
			return nil, nil
		}
		return u, nil
	}
}

// getURL fetches the body of a URL.
func getURL(u string, cfg httpConfig) (io.Reader, error) {
	tr := &http.Transport{
		Proxy: proxyFunc(cfg),
		TLSClientConfig: &tls.Config{
			InsecureSkipVerify: cfg.insecure,
		},
	}
	client := &http.Client{Transport: tr}

	req, err := http.NewRequest("GET", u, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "gron/"+version)
	req.Header.Set("Accept", "application/json")

	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	return resp.Body, nil
}
