package main

import (
	"strings"
)

// colourJSON adds ANSI colours to a compact JSON document.
func colourJSON(in []byte) string {
	var b strings.Builder
	// stack of containers: 'o' for object, 'a' for array
	var stack []byte
	// whether the next string in the current object is a key
	expectKey := false

	inObject := func() bool {
		return len(stack) > 0 && stack[len(stack)-1] == 'o'
	}

	i := 0
	for i < len(in) {
		c := in[i]
		switch c {
		case '{':
			b.WriteString(colBrace.wrap("{"))
			stack = append(stack, 'o')
			expectKey = true
			i++
		case '[':
			b.WriteString(colBrace.wrap("["))
			stack = append(stack, 'a')
			expectKey = false
			i++
		case '}', ']':
			b.WriteString(colBrace.wrap(string(c)))
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			expectKey = false
			i++
		case ':':
			b.WriteString(colPunct.wrap(":"))
			expectKey = false
			i++
		case ',':
			b.WriteString(colPunct.wrap(","))
			expectKey = inObject()
			i++
		case '"':
			end := scanString(in, i)
			content := string(in[i+1 : end-1])
			if expectKey && inObject() {
				b.WriteString(colKey.wrap("\""))
				b.WriteString(colKey.wrap(content))
				b.WriteString(colKey.wrap("\""))
			} else {
				b.WriteString(colQuote.wrap("\""))
				b.WriteString(colString.wrap(content))
				b.WriteString(colQuote.wrap("\""))
			}
			i = end
		case ' ', '\t', '\n', '\r':
			b.WriteByte(c)
			i++
		default:
			// literal: number, true, false or null
			start := i
			for i < len(in) {
				d := in[i]
				if d == ',' || d == '}' || d == ']' || d == ':' || d == ' ' || d == '\n' || d == '\t' || d == '\r' {
					break
				}
				i++
			}
			lit := string(in[start:i])
			switch lit {
			case "true", "false", "null":
				b.WriteString(colBool.wrap(lit))
			default:
				b.WriteString(colNumber.wrap(lit))
			}
		}
	}
	return b.String()
}

// scanString returns the index just past the closing quote of the JSON
// string starting at in[start].
func scanString(in []byte, start int) int {
	i := start + 1
	for i < len(in) {
		switch in[i] {
		case '\\':
			i += 2
			continue
		case '"':
			return i + 1
		}
		i++
	}
	return len(in)
}
