// ensureStdFds makes sure the standard descriptors exist. If any of them was
// closed before the program started, /dev/null is opened in its place so
// that reads see EOF and writes are discarded rather than failing.
func ensureStdFds() {
	for fd := 0; fd <= 2; fd++ {
		_, _, errno := syscall.Syscall(syscall.SYS_FCNTL, uintptr(fd), syscall.F_GETFD, 0)
		if errno != syscall.EBADF {
			continue
		}
		nfd, err := syscall.Open("/dev/null", syscall.O_RDWR, 0)
		if err != nil {
			continue
		}
		if nfd != fd {
			syscall.Dup2(nfd, fd)
			syscall.Close(nfd)
		}
	}
}
